{"command":"mkdir -p src && cat > src/math.hpp <<'EOF'
#pragma once
#include <cmath>
#include <algorithm>

struct Vec3 {
    float x=0, y=0, z=0;
    Vec3() = default;
    Vec3(float a,float b,float c):x(a),y(b),z(c){}
    Vec3 operator+(Vec3 a)const{return {x+a.x,y+a.y,z+a.z};}
    Vec3 operator-(Vec3 a)const{return {x-a.x,y-a.y,z-a.z};}
    Vec3 operator*(float a)const{return {x*a,y*a,z*a};}
    Vec3 operator/(float a)const{return {x/a,y/a,z/a};}
    float dot(Vec3 a)const{return x*a.x+y*a.y+z*a.z;}
    Vec3 cross(Vec3 a)const{return {y*a.z-z*a.y,z*a.x-x*a.z,x*a.y-y*a.x};}
    float length()const{return std::sqrt(dot(*this));}
    Vec3 unit()const{return *this/length();}
};

inline Vec3 rotate(Vec3 p,Vec3 angles) {
    float s=std::sin(angles.x), c=std::cos(angles.x);
    p={p.x,p.y*c-p.z*s,p.y*s+p.z*c};
    s=std::sin(angles.y);c=std::cos(angles.y);
    p={p.x*c+p.z*s,p.y,-p.x*s+p.z*c};
    s=std::sin(angles.z);c=std::cos(angles.z);
    return {p.x*c+p.y*s,-p.x*s+p.y*c,p.z};
}
