#include "../src/math.hpp"
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <array>
using namespace std;

int main(int argc,char**argv){
 ifstream input(argv[1]);int w=stoi(argv[2]),h=stoi(argv[3]);Vec3 ang;int btype=0,ntype=0;
 if(argc>6)ang={stof(argv[4]),stof(argv[5]),stof(argv[6])};
 if(argc>7)btype=stoi(argv[7]);if(argc>8)ntype=stoi(argv[8]);
 vector<Vec3> vertices;vector<array<int,3>> faces;
 string line;float maxv=0;
 while(getline(input,line)){istringstream in(line);string op;in>>op;if(op=="v"){Vec3 v;in>>v.x>>v.y>>v.z;vertices.push_back(v);maxv=max({maxv,v.x,v.y,v.z});}else if(op=="f"){array<int,3> f;in>>f[0]>>f[1]>>f[2];for(int&i:f)--i;faces.push_back(f);}}
 vector<char> out((w+1)*h,' ');vector<float> depth(out.size(),-INFINITY);
 for(auto f:faces){
  Vec3 a=vertices[f[0]],b=vertices[f[1]],c=vertices[f[2]];
  Vec3 nor=(b-a).cross(c-a).unit();
  nor=rotate(nor,ang);
  a=rotate(a,ang);b=rotate(b,ang);c=rotate(c,ang);
  if(ntype>=2)nor=(b-a).cross(c-a).unit();
  auto proj=[&](Vec3 p){p=p/maxv;float s=min(w/4.0f,h/2.0f);return Vec3(-p.x*s+w/4.0f,-p.y*s+h/2.0f,p.z);};
  a=proj(a);b=proj(b);c=proj(c);
  int miny=ceil(max(1.f,min({a.y,b.y,c.y}))),maxy=ceil(min(h-1.f,max({a.y,b.y,c.y})));
  int minx=ceil(max(1.f,min({a.x,b.x,c.x}))),maxx=floor(min(w-1.f,max({a.x,b.x,c.x})));
  cerr<<"p "<<a.x<<","<<a.y<<" "<<b.x<<","<<b.y<<" "<<c.x<<","<<c.y<<" intensity "<<nor.z<<"\n";
  for(int y=miny;y<maxy;y++){
   out[y*w+1]='\n';
   for(int x=minx;x<=maxx;x++){
    Vec3 bc;
    if(btype==0){
     Vec3 ux{c.x-a.x,b.x-a.x,a.x-x},uy{c.y-a.y,b.y-a.y,a.y-y};Vec3 u=ux.cross(uy);
     bc={1.f-(u.x+u.y)/u.z,u.y/u.z,u.x/u.z};
    } else if(btype==1) {
     float ar=(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
     bc={((b.x-x)*(c.y-y)-(b.y-y)*(c.x-x))/ar,((c.x-x)*(a.y-y)-(c.y-y)*(a.x-x))/ar,((a.x-x)*(b.y-y)-(a.y-y)*(b.x-x))/ar};
    } else if(btype==2){
     float ar=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);
     float u=((b.y-c.y)*(x-c.x)+(c.x-b.x)*(y-c.y))/ar,v=((c.y-a.y)*(x-c.x)+(a.x-c.x)*(y-c.y))/ar;
     bc={u,v,1-u-v};
    } else {
     Vec3 u=b-a,v=c-a,t=Vec3(x,y,0)-a;u.z=v.z=t.z=0;
     float uu=u.dot(u),uv=u.dot(v),vv=v.dot(v),tu=t.dot(u),tv=t.dot(v),d=uu*vv-uv*uv;
     float by=(vv*tu-uv*tv)/d,bz=(uu*tv-uv*tu)/d;
     bc={1-by-bz,by,bz};
    }
    if(bc.x<0||bc.y<0||bc.z<0)continue;
    float intensity=nor.z;
    if(ntype%2==1)intensity=bc.x*intensity+bc.y*intensity+bc.z*intensity;
    if(intensity<=0)continue;
    char ch=' ';
    if(intensity>=0&&intensity<=1){int k=int(intensity*10);ch="..:-=+*#%@@"[k];}
    int idx=y*w+2*x;
    if(idx+1<out.size()){out[idx]=ch;out[idx+1]=ch;}
   }
  }
 }
 cout.write(out.data(),out.size());
}
