    for(auto& model:models)for(auto& t:model.triangles)for(auto& v:t.p)m=max({m,v.x,v.y,v.z});
    float scale=min(w/4.f,h/2.f);
    for(auto& model:models)for(auto& t:model.triangles) {
        Vec3 n=(t.p[1]-t.p[0]).cross(t.p[2]-t.p[0]).unit();
        n=rotate(n,angle);
        Vec3 p[3];
        for(int i=0;i<3;++i) {
            Vec3 v=rotate(t.p[i]/m,angle);
            p[i]={-v.x*scale+w/4.f,-v.y*scale+h/2.f,v.z};
        }
        Vec3 a=p[0],b=p[1],c=p[2];
        int lo_y=ceil(max(1.f,min({a.y,b.y,c.y}))),hi_y=ceil(min(h-1.f,max({a.y,b.y,c.y})));
        int lo_x=ceil(max(1.f,min({a.x,b.x,c.x}))),hi_x=floor(min(w-1.f,max({a.x,b.x,c.x})));
        for(int y=lo_y;y<hi_y;++y) {
            pixels[y*w+1].glyph='\n';
            for(int x=lo_x;x<=hi_x;++x) {
                Vec3 q=Vec3(c.x-a.x,b.x-a.x,a.x-x).cross({c.y-a.y,b.y-a.y,a.y-y});
                if(q.z==0.f)continue;
                Vec3 bc={1.f-(q.x+q.y)/q.z,q.y/q.z,q.x/q.z};
                if(bc.x<0.f||bc.y<0.f||bc.z<0.f)continue;
                float intensity=bc.x*n.z+bc.y*n.z+bc.z*n.z;
                if(intensity<=0.f)continue;
                float z=bc.x*a.z+bc.y*b.z+bc.z*c.z;
                size_t ix=y*w+x*2;
                if(ix+1>=pixels.size())continue;
                if(z<depths[ix])continue;
                depths[ix]=z;
                pixels[ix]={shade(intensity),t.color};pixels[ix+1]=pixels[ix];
            }
        }
    }
    return pixels;
}

string format_image(const vector<Pixel>& pixels,bool no_color,bool web) {
    string out;out.reserve(pixels.size()*(no_color?1:42));
    for(auto& p:pixels) {
        if(no_color) {out+=p.glyph;continue;}
        const auto& c=p.color;
        if(web)out+="<span style=\"color:rgb("+to_string(c.r)+","+to_string(c.g)+","+to_string(c.b)+")\">";
        else out+="\x1b[48;2;25;25;25m\x1b[38;2;"+to_string(c.r)+";"+to_string(c.g)+";"+to_string(c.b)+"m";
        out+=p.glyph;
        if(!web)out+="\x1b[49m\x1b[39m";
    }
    if(no_color)out+='\n';
    return out;
}
