static double similarity(const string& a,const string& b) {
    // Jaro-Winkler similarity for misspelled long option suggestions.
    if(a==b)return 1.;
    int span=max(a.size(),b.size())/2-1;
    vector<bool> am(a.size()),bm(b.size());int matches=0;
    for(int i=0;i<(int)a.size();++i)for(int j=max(0,i-span);j<min((int)b.size(),i+span+1);++j)
        if(!bm[j]&&a[i]==b[j]) {am[i]=bm[j]=true;++matches;break;}
    if(!matches)return 0;
    int j=0,trans=0;
    for(int i=0;i<(int)a.size();++i)if(am[i]) {while(!bm[j])++j;if(a[i]!=b[j++])++trans;}
    double score=(double(matches)/a.size()+double(matches)/b.size()+(matches-trans/2.)/matches)/3.;
    int pre=0;while(pre<4&&pre<(int)min(a.size(),b.size())&&a[pre]==b[pre])++pre;
    return score+pre*.1*(1-score);
}
